-- Trusted operator evidence, with no client write or command that certifies itself.
create table app_private.backup_health_events (
  id uuid primary key default gen_random_uuid(),
  event_order bigint generated always as identity unique,
  term_id uuid not null references public.terms(id),
  generation_id uuid not null,
  phase text not null check (phase in ('backup','restore')),
  outcome text not null check (outcome in ('started','verified','failed','blocked')),
  evidence_scope text not null check (evidence_scope in ('synthetic','operational')),
  blocker text check (blocker in ('device','provider','key','ledger','target','custody')),
  captured_at timestamptz,
  evidence_sha256 text check (evidence_sha256 ~ '^[a-f0-9]{64}$'),
  disposition_head_sha256 text check (disposition_head_sha256 ~ '^[a-f0-9]{64}$'),
  recorded_at timestamptz not null default statement_timestamp(),
  check ((outcome = 'blocked') = (blocker is not null)),
  check (case when outcome = 'verified' then captured_at is not null and evidence_sha256 is not null
    else captured_at is null and evidence_sha256 is null end),
  check ((phase = 'restore' and outcome = 'verified') = (disposition_head_sha256 is not null)),
  check (captured_at is null or (isfinite(captured_at) and captured_at <= recorded_at)),
  check (isfinite(recorded_at))
);
create index backup_health_latest on app_private.backup_health_events(term_id, evidence_scope, phase, recorded_at desc, event_order desc);
alter table app_private.backup_health_events enable row level security;
alter table app_private.backup_health_events force row level security;
revoke all on app_private.backup_health_events from public, anon, authenticated, service_role;
create trigger immutable_backup_health_event before update or delete on app_private.backup_health_events
  for each row execute function app_private.request_history_guard();


create function app_private.backup_disposition_fingerprint(p_term_id uuid) returns text
language sql stable security definer set search_path = '' as $$
  select encode(sha256(convert_to(coalesce(jsonb_agg(
    jsonb_build_array(t.id,coalesce(h.sequence,0),coalesce(h.entry_hash,repeat('0',64))) order by t.id
  )::text,'[]'),'UTF8')),'hex')
  from public.terms t left join public.disposition_heads h on h.term_id=t.id
  where t.organization_id=(select organization_id from public.terms where id=p_term_id)
$$;
revoke all on function app_private.backup_disposition_fingerprint(uuid) from public, anon, authenticated, service_role;

create function public.read_backup_health(p_term_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare latest_backup app_private.backup_health_events; latest_restore app_private.backup_health_events;
  last_verified app_private.backup_health_events; backup_status text; restore_status text;
  replay_required boolean; checked_at timestamptz := statement_timestamp();
begin
  perform app_private.request_actor(p_term_id);
  if not app_private.privacy_custodian(p_term_id) then
    raise exception using errcode='42501', message='command_permission_denied';
  end if;

  select * into latest_backup from app_private.backup_health_events
  where term_id=p_term_id and evidence_scope='operational' and phase='backup' and recorded_at <= checked_at
  order by recorded_at desc, event_order desc limit 1;
  select * into latest_restore from app_private.backup_health_events
  where term_id=p_term_id and evidence_scope='operational' and phase='restore' and recorded_at <= checked_at
  order by recorded_at desc, event_order desc limit 1;
  select * into last_verified from app_private.backup_health_events
  where term_id=p_term_id and evidence_scope='operational' and phase='backup'
    and outcome='verified' and recorded_at <= checked_at
  order by captured_at desc, recorded_at desc, event_order desc limit 1;

  backup_status := case
    when latest_backup.id is null then 'missing'
    when latest_backup.outcome = 'started' and latest_backup.recorded_at <= checked_at - interval '24 hours' then 'interrupted'
    when latest_backup.outcome <> 'verified' then latest_backup.outcome
    when latest_backup.captured_at <= checked_at - interval '24 hours' then 'stale'
    else 'verified'
  end;
  replay_required := app_private.disposition_replay_required(p_term_id);
  restore_status := case
    when replay_required then 'blocked'
    when latest_restore.id is null then 'missing'
    when latest_restore.outcome = 'started' and latest_restore.recorded_at <= checked_at - interval '24 hours' then 'interrupted'
    when latest_restore.outcome <> 'verified' then latest_restore.outcome
    when backup_status <> 'verified' or latest_restore.generation_id <> latest_backup.generation_id
      or latest_restore.captured_at <> latest_backup.captured_at
      or latest_restore.recorded_at < latest_backup.recorded_at
      or latest_restore.disposition_head_sha256 is distinct from app_private.backup_disposition_fingerprint(p_term_id) then 'pending'
    else 'verified'
  end;

  -- Recovery metadata must stay accessible while private contents are quarantined.
  -- Use the original minimal audit writer, as this projection is recovery metadata.
  perform app_private.record_content_read_before_disposition('read_backup_health',p_term_id,null,true);
  return jsonb_build_object(
    'checkedAt',checked_at, 'backupStatus',backup_status, 'restoreStatus',restore_status,
    'backupBlocker',latest_backup.blocker,
    'restoreBlocker',case when replay_required then 'ledger' else latest_restore.blocker end,
    'lastVerifiedBackupAt',last_verified.captured_at,
    'lastBackupAttemptAt',latest_backup.recorded_at, 'lastRestoreAttemptAt',latest_restore.recorded_at,
    'backupFreshUntil',case when backup_status='verified' then latest_backup.captured_at+interval '24 hours' end,
    'backupEvidence',case when latest_backup.outcome='verified' then latest_backup.evidence_sha256 end,
    'restoreEvidence',case when restore_status='verified' then latest_restore.evidence_sha256 end
  );
end;
$$;
revoke all on function public.read_backup_health(uuid) from public, anon, authenticated, service_role;
grant execute on function public.read_backup_health(uuid) to authenticated;
